import React, { useState, useEffect } from "react";
import ChartistGraph from "react-chartist";
import 'chartist/dist/chartist.min.css'; // ต้อง import css เพื่อให้เส้นขึ้น

import {
  Container,
  Row,
  Col,
  Card,
  Table,
} from "react-bootstrap";

function Dashboard() {
  // ค่าเริ่มต้น: ใส่ข้อมูลหลอกๆ ไว้ก่อน เพื่อให้เห็นว่ากราฟทำงานได้ (ถ้า Fetch สำเร็จ ข้อมูลนี้จะถูกทับ)
  const [chartData, setChartData] = useState({
    labels: ['07:00', '08:00', '09:00', '10:00', '11:00'],
    series: [
      [0, 0, 0, 0, 0], // เส้นที่ 1
      [0, 0, 0, 0, 0], // เส้นที่ 2
      [0, 0, 0, 0, 0], // เส้นที่ 3
      [0, 0, 0, 0, 0]  // เส้นที่ 4
    ]
  });

  // State สำหรับเก็บข้อมูลตาราง (ถ้ามี)
  const [tableData, setTableData] = useState([]);

  useEffect(() => {
    // ฟังก์ชันดึงข้อมูลจาก Backend
    const fetchData = async () => {
      try {
        // ยิงไปที่ Port 3001 (Backend)
        const response = await fetch('http://localhost:3001/api/chart-data');
        const result = await response.json();

        console.log("🔥 Data from Backend:", result); // เช็คใน Console (F12) ดูว่าข้อมูลมาไหม

        if (result && result.series) {
          setChartData(result);

          // (Option) เอาข้อมูลมาทำตารางสรุป
          // setTableData(...) 
        }
      } catch (error) {
        console.error("❌ Error fetching data:", error);
      }
    };

    fetchData(); // รันครั้งแรกทันที
    const interval = setInterval(fetchData, 5000); // รันซ้ำทุก 5 วินาที
    return () => clearInterval(interval);
  }, []);

  // ตั้งค่ากราฟ
  const options = {
    lineSmooth: true, // เส้นโค้ง
    low: 0,
    high: 20, // ปรับแกน Y สูงสุด (ถ้าคนเยอะกว่า 20 ให้เพิ่มเลขนี้)
    showArea: false,
    axisX: {
      showGrid: false,
    },
    chartPadding: {
      right: 40,
      left: 10
    }
  };

  // ตั้งค่า Responsive
  const responsiveOptions = [
    ['screen and (max-width: 640px)', {
      axisX: {
        labelInterpolationFnc: function (value) {
          return value[0];
        }
      }
    }]
  ];

  return (
    <>
      <Container fluid>
        <Row>
          <Col md="12">
            <Card>
              <Card.Header>
                <Card.Title as="h4">จำนวนผู้โดยสาร (Passenger Density)</Card.Title>
                <p className="card-category">ข้อมูลเรียลไทม์ (อัปเดตทุก 5 วินาที)</p>
              </Card.Header>
              <Card.Body>
                <div className="ct-chart" id="chartHours">
                    {/* Legend: บอกสีของแต่ละเส้น */}
                    <div style={{ display: 'flex', gap: '15px', marginBottom: '10px', fontSize: '14px' }}>
                        <span style={{color: '#1DC7EA'}}>■ วิศวะ (ฟ้า)</span>
                        <span style={{color: '#FB404B'}}>■ วิทยาศาสตร์ (แดง)</span>
                        <span style={{color: '#FF9500'}}>■ ศิลปศาสตร์ (ส้ม)</span>
                        <span style={{color: '#9368E9'}}>■ PKY (ม่วง)</span>
                    </div>

                    <ChartistGraph
                      data={chartData}
                      type="Line"
                      options={options}
                      responsiveOptions={responsiveOptions}
                    />
                </div>
              </Card.Body>
              <Card.Footer>
                <div className="stats">
                  <i className="fa fa-history" /> Updated 3 minutes ago
                </div>
              </Card.Footer>
            </Card>
          </Col>
        </Row>

        {/* ตารางแสดงข้อมูลดิบ (ช่วยเช็คว่าข้อมูลเข้ามาจริงไหม) */}
        <Row>
          <Col md="12">
            <Card>
              <Card.Header>
                <Card.Title as="h4">Debug Data</Card.Title>
                <p className="card-category">ตรวจสอบค่าที่ได้จาก Database</p>
              </Card.Header>
              <Card.Body>
                  <div style={{maxHeight: '200px', overflowY: 'scroll'}}>
                      <pre>{JSON.stringify(chartData, null, 2)}</pre>
                  </div>
              </Card.Body>
            </Card>
          </Col>
        </Row>
      </Container>
    </>
  );
}

export default Dashboard;
